export const buttonLinkStyles = tv({
  extend: buttonStyles,
  base: "cursor-pointer",
});

export type ButtonVariant = NonNullable<
  VariantProps<typeof buttonStyles>["variant"]
>;
export type ButtonSize = NonNullable<VariantProps<typeof buttonStyles>["size"]>;

"use client";

import { type MotionProps, motion, useReducedMotion } from "motion/react";
import {
  Button as AriaButton,
  type ButtonProps as AriaButtonProps,
  composeRenderProps,
} from "react-aria-components";
import { springLayout } from "./motion";
import {
  type ButtonSize,
  type ButtonVariant,
  buttonStyles,
} from "./button-styles";

export interface ButtonProps
  extends Omit<
    AriaButtonProps,
    | "style"
    | "onAnimationStart"
    | "onAnimationEnd"
    | "onAnimationIteration"
    | "onHoverStart"
    | "onHoverEnd"
  > {
  ref?: React.Ref<HTMLButtonElement>;
  variant?: ButtonVariant;
  size?: ButtonSize;
  static?: boolean;
  layout?: MotionProps["layout"];
}

const MotionButton = motion.create(AriaButton);

const pressStyles = "motion-safe:pressed:not-aria-expanded:scale-[0.96]";

export function Button({
  className,
  variant = "default",
  size = "default",
  static: isStatic = false,
  layout,
  ...props
}: ButtonProps) {
  const reduceMotion = useReducedMotion();
  return (
    <MotionButton
      data-slot="button"
      data-variant={variant}
      data-size={size}
      layout={reduceMotion ? false : layout}
      transition={springLayout}
      className={composeRenderProps(className, (className) =>
        buttonStyles({
          variant,
          size,
          className: [!isStatic && pressStyles, className],
        }),
      )}
      {...props}
    />
  );
}

"use client";

import { LayoutGroup } from "motion/react";
import { createContext, useId } from "react";
import {
  ToggleButtonGroup as AriaToggleButtonGroup,
  composeRenderProps,
  type ToggleButtonGroupProps,
} from "react-aria-components";
import { cn } from "./utils";

export const SingleToggleGroupContext = createContext(false);

export function ToggleButtonGroup({
  className,
  ...props
}: ToggleButtonGroupProps) {
  const groupId = useId();
  return (
    <LayoutGroup id={groupId}>
      <SingleToggleGroupContext.Provider
        value={props.selectionMode !== "multiple"}
      >
        <AriaToggleButtonGroup
          {...props}
          data-slot="toggle-button-group"
          className={composeRenderProps(className, (className) =>
            cn(
              "inline-flex w-fit max-w-full flex-wrap gap-1 rounded-lg border border-border bg-secondary p-1 data-[orientation=vertical]:flex-col",
              className,
            ),
          )}
        />
      </SingleToggleGroupContext.Provider>
    </LayoutGroup>
  );
}

"use client";

import { motion, useReducedMotion } from "motion/react";
import { useContext } from "react";
import {
  ToggleButton as AriaToggleButton,
  composeRenderProps,
  type ToggleButtonProps,
} from "react-aria-components";
import { tv, type VariantProps } from "tailwind-variants";
import { springLayout, transitionFor } from "./motion";
import { cn } from "./utils";
import { SingleToggleGroupContext } from "./toggle-button-group";

const toggleButtonStyles = tv({
  base: "inline-flex min-h-11 cursor-pointer items-center justify-center gap-2 rounded-md px-4 text-sm font-medium transition-[color,background-color,border-color,box-shadow,scale] duration-150 ease-[cubic-bezier(0.23,1,0.32,1)] motion-safe:pressed:scale-[0.96] disabled:cursor-default disabled:opacity-50 focus-visible:z-10 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring [&_svg]:pointer-events-none [&_svg]:shrink-0",
  variants: {
    variant: {
      default:
        "border border-border bg-card text-foreground shadow-[var(--shadow-card)] hover:bg-muted pressed:bg-muted selected:border-primary/40 selected:bg-accent selected:text-accent-foreground",
      segmented:
        "border border-transparent bg-transparent px-3 text-muted-foreground shadow-none hover:bg-card/70 hover:text-foreground pressed:bg-card/70 selected:border-border selected:bg-card selected:text-foreground selected:shadow-[var(--shadow-card)] sm:min-h-9",
      ghost:
        "border border-transparent bg-transparent text-foreground hover:bg-muted pressed:bg-muted selected:bg-accent selected:text-accent-foreground",
    },
  },
  defaultVariants: { variant: "default" },
});

export interface ToggleButtonStyleProps extends ToggleButtonProps {
  variant?: NonNullable<VariantProps<typeof toggleButtonStyles>["variant"]>;
}

export function ToggleButton({
  className,
  children,
  variant = "default",
  ...props
}: ToggleButtonStyleProps) {
  const reduceMotion = useReducedMotion();
  const groupedSelection =
    useContext(SingleToggleGroupContext) && variant === "segmented";
  return (
    <AriaToggleButton
      {...props}
      data-slot="toggle-button"
      data-variant={variant}
      className={composeRenderProps(className, (className) =>
        toggleButtonStyles({
          variant,
          className: cn(
            groupedSelection &&
              "relative isolate selected:border-transparent selected:bg-transparent selected:shadow-none",
            className,
          ),
        }),
      )}
    >
      {composeRenderProps(children, (content, { isSelected }) => (
        <>
          {groupedSelection && isSelected && (
            <motion.span
              layoutId="toggle-group-selection"
              initial={false}
              aria-hidden="true"
              transition={transitionFor(reduceMotion, springLayout)}
              className="pointer-events-none absolute inset-0 -z-10 rounded-md border border-border bg-card shadow-[var(--shadow-card)] forced-colors:border-[Highlight]"
            />
          )}
          {content}
        </>
      ))}
    </AriaToggleButton>
  );
}

"use client";

import { CheckIcon } from "@phosphor-icons/react";
import { useState } from "react";
import { AnimatedNumber } from "../../../components/vip-ui/animated-number";
import { Badge } from "../../../components/vip-ui/badge";
import { Button } from "../../../components/vip-ui/button";
import { ToggleButton } from "../../../components/vip-ui/toggle-button";
import { ToggleButtonGroup } from "../../../components/vip-ui/toggle-button-group";
import { cn } from "../../../components/vip-ui/utils";

type Cycle = "monthly" | "yearly";

const plans = [
  {
    name: "Starter",
    description: "For one person who wants to try the product.",
    monthly: 0,
    yearly: 0,
    action: "Start for free",
    features: ["1 project", "3 team members", "10 GB storage", "Email help"],
  },
  {
    name: "Pro",
    description: "For small teams that ship each week.",
    monthly: 24,
    yearly: 19,
    action: "Start a free trial",
    popular: true,
    features: [
      "Unlimited projects",
      "10 team members",
      "100 GB storage",
      "Custom domains",
      "Help in 24 hours",
    ],
  },
  {
    name: "Business",
    description: "For companies with security and audit needs.",
    monthly: 59,
    yearly: 47,
    action: "Talk to sales",
    features: [
      "Everything in Pro",
      "50 team members",
      "1 TB storage",
      "Single sign-on",
      "Audit log",
    ],
  },
];

const priceFormat: Intl.NumberFormatOptions = {
  style: "currency",
  currency: "USD",
  maximumFractionDigits: 0,
};

export function PricingPlans() {
  const [cycle, setCycle] = useState<Cycle>("monthly");

  return (
    <section aria-labelledby="pricing-title">
      <div className="mx-auto max-w-2xl text-center">
        <Badge variant="accent">Pricing</Badge>
        <h1
          id="pricing-title"
          className="mt-4 text-balance text-4xl font-semibold tracking-[-0.055em] sm:text-5xl"
        >
          A plan for each stage of your team
        </h1>
        <p className="mt-4 text-base leading-7 text-muted-foreground">
          Start for free. Change or cancel your plan at any time.
        </p>
        <ToggleButtonGroup
          aria-label="Billing cycle"
          selectionMode="single"
          disallowEmptySelection
          selectedKeys={[cycle]}
          onSelectionChange={(keys) => {
            const [next] = keys;
            if (next === "monthly" || next === "yearly") setCycle(next);
          }}
          className="mx-auto mt-8 rounded-full"
        >
          <ToggleButton
            id="monthly"
            variant="segmented"
            className="rounded-full px-4"
          >
            Monthly
          </ToggleButton>
          <ToggleButton
            id="yearly"
            variant="segmented"
            className="rounded-full px-4"
          >
            Yearly
            <span className="rounded-full bg-success-subtle px-2 py-0.5 text-[11px] font-semibold text-success-foreground">
              −20%
            </span>
          </ToggleButton>
        </ToggleButtonGroup>
      </div>
      <ul className="mt-12 grid gap-5 lg:grid-cols-3">
        {plans.map((plan) => (
          <li
            key={plan.name}
            className={cn(
              "relative flex flex-col rounded-2xl bg-card p-6 shadow-[var(--shadow-card)] ring-1 ring-border/70 sm:p-8",
              plan.popular && "ring-2 ring-primary lg:-my-3 lg:py-11",
            )}
          >
            {plan.popular && (
              <Badge
                variant="accent"
                className="absolute -top-3.5 start-1/2 -translate-x-1/2 rtl:translate-x-1/2"
              >
                Most popular
              </Badge>
            )}
            <h2 className="text-lg font-semibold tracking-[-0.03em]">
              {plan.name}
            </h2>
            <p className="mt-1 text-sm leading-6 text-muted-foreground">
              {plan.description}
            </p>
            <p className="mt-6 flex items-baseline gap-1">
              <AnimatedNumber
                value={plan[cycle]}
                formatOptions={priceFormat}
                className="text-4xl font-semibold tracking-[-0.05em]"
              />
              <span className="text-sm text-muted-foreground">
                per seat each month
              </span>
            </p>
            <p className="mt-1 h-5 text-xs text-muted-foreground">
              {cycle === "yearly" && plan.yearly > 0
                ? `$${plan.yearly * 12} billed once a year`
                : ""}
            </p>
            <Button
              variant={plan.popular ? "default" : "outline"}
              className="mt-6 w-full"
            >
              {plan.action}
            </Button>
            <ul className="mt-8 grid gap-3 border-t border-border/70 pt-6 text-sm">
              {plan.features.map((feature) => (
                <li key={feature} className="flex items-center gap-3">
                  <CheckIcon
                    size={16}
                    weight="bold"
                    className="shrink-0 text-primary"
                    aria-hidden="true"
                  />
                  {feature}
                </li>
              ))}
            </ul>
          </li>
        ))}
      </ul>
      <p className="mt-10 text-center text-sm text-muted-foreground">
        Prices are in US dollars. Taxes can apply.
      </p>
    </section>
  );
}
